# Brazilian Portuguese starts from the European table and overrides only where the two genuinely
# differ -- orthography ("detetadas"/"detectadas", "ficheiro"/"arquivo"), and the gerund where
# European Portuguese uses "a" plus the infinitive. Copying all sixty strings and editing a dozen
# by hand is how two pages drift apart one row at a time.
STRINGS["pt-BR"] = dict(STRINGS["pt-PT"])
